package com.primehr.succession;
import com.primehr.integration.humanresource.HumanResourceAssessmentSubject; import com.primehr.succession.domain.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import static org.assertj.core.api.Assertions.*;
class SuccessionFoundationDomainTest {
 @Test void policyIsVersionedPrivateAndLifecycleControlled(){var p=new SuccessionGovernancePolicyVersion("A","P",1,null,"Policy",null,"CSC Resolution 2600005","Agency policy","Privacy notice","Eligibility","Evidence",12,24,5,true,true,true,true,true);assertThat(p.getStatus()).isEqualTo(SuccessionDefinitionStatus.DRAFT);p.publish(LocalDate.of(2026,1,1),null,"admin",Instant.now());assertThatThrownBy(()->p.update("Changed",null,"basis","ref","privacy","eligibility","evidence",12,24,5,true,true,true,true,true)).isInstanceOf(RuntimeException.class);}
 @Test void readinessAndCommitteeRulesRejectUnsafeConfiguration(){assertThatThrownBy(()->new SuccessionReadinessLevel("A","S","READY","Ready","desc","guidance",0,true,1)).hasMessageContaining("positive");assertThatThrownBy(()->new SuccessionCommitteeCharterVersion("A","C",1,null,"Committee",null,"CSC policy","Office order",SuccessionCommitteeCharterVersion.QuorumType.PERCENTAGE,new BigDecimal("101"),true,true,true)).hasMessageContaining("exceed 100");}
 @Test void authoritativeMemberSnapshotRejectsIneligibleEmployeeAndSecretariatVote(){var source=new HumanResourceAssessmentSubject(1L,"EMP-1","Employee",false,2L,null,3L,4L,"fingerprint",null,Instant.now());assertThatThrownBy(()->new SuccessionCommitteeMember("A","C",source,SuccessionCommitteeMember.Role.MEMBER,true,LocalDate.now(),null)).hasMessageContaining("eligible");var eligible=new HumanResourceAssessmentSubject(1L,"EMP-1","Employee",true,2L,null,3L,4L,"fingerprint",null,Instant.now());assertThatThrownBy(()->new SuccessionCommitteeMember("A","C",eligible,SuccessionCommitteeMember.Role.SECRETARIAT,true,LocalDate.now(),null)).hasMessageContaining("cannot vote");}
}
